function validate([s, t]) {
  if (typeof s !== 'string' || typeof t !== 'string') return 's and t must be strings.';
  if (s.length < 1 || s.length > 50000) return 's needs 1 to 50000 letters.';
  if (s.length !== t.length) return 's and t must have the same length.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(t)) return 's and t contain only lowercase English letters.';
  return null;
}

