function minSteps(s, t) {
  const count = new Array(26).fill(0);

  for (let i = 0; i < s.length; i++) {
    count[s.charCodeAt(i) - 97]++;
    count[t.charCodeAt(i) - 97]--;
  }

  let steps = 0;
  for (const diff of count) {
    if (diff > 0) {
      steps += diff;
    }
  }
  return steps;
}

