function minSteps(s, t) {
  // Sort both strings and pair up equal letters; every letter of t left unpaired must be rewritten.
  const a = s.split('').sort();
  const b = t.split('').sort();
  let i = 0, j = 0, matched = 0;
  while (i < a.length && j < b.length) {
    if (a[i] === b[j]) { matched++; i++; j++; }
    else if (a[i] < b[j]) i++;
    else j++;
  }
  return t.length - matched;
}

