function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 9000 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 9);
  const alphabet = large ? 1 + Math.floor(rand() * 26) : 1 + Math.floor(rand() * 5);
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * alphabet));
  const s = Array.from({ length: n }, letter);
  let t;
  const mode = rand();
  if (mode < 0.25) {
    // A shuffled copy of s: already an anagram.
    t = s.slice();
    for (let i = t.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [t[i], t[j]] = [t[j], t[i]];
    }
  } else if (mode < 0.6) {
    // A copy of s with a few positions rewritten.
    t = s.slice();
    const changes = Math.floor(rand() * (Math.min(n, large ? 500 : 3) + 1));
    for (let k = 0; k < changes; k++) t[Math.floor(rand() * n)] = String.fromCharCode(97 + Math.floor(rand() * 26));
  } else {
    t = Array.from({ length: n }, letter);
  }
  return [s.join(''), t.join('')];
}
